def-hyp[predicate](
    list-partial(
        Type.annotation(@A, Set(T@Set.ctxt.T)),
        Type.annotation(@x, T@Set.ctxt.T),
        Set.mem(x, S@Topology.ctxt.S)
    ),
    Topology.isolatedPoint(x, A),
    Logic.and(
        Set.mem(x, A),
        Logic.neg(Set.mem(x, Topology.derivedSet(A)))
    )
)
